const LDAPOutpostConfigSchema = z
  .object({
    pk: z.int().openapi({ readOnly: true, title: 'ID' }),
    name: z.string(),
    base_dn: z
      .string()
      .exactOptional()
      .openapi({ description: 'DN under which objects are accessible.' }),
    bind_flow_slug: z.string(),
    unbind_flow_slug: z
      .string()
      .nullable()
      .openapi({
        description: "Get slug for unbind flow, defaulting to brand's default flow.",
        readOnly: true,
      }),
    application_slug: z
      .string()
      .openapi({
        description: 'Prioritize backchannel slug over direct application slug',
        readOnly: true,
      }),
    certificate: z.uuid().nullable().exactOptional(),
    tls_server_name: z.string().exactOptional(),
    uid_start_number: z
      .int()
      .min(-2147483648)
      .max(2147483647)
      .exactOptional()
      .openapi({
        description:
          "The start for uidNumbers, this number is added to the user.pk to make sure that the numbers aren't too low for POSIX users. Default is 2000 to ensure that we don't collide with local users uidNumber",
      }),
    gid_start_number: z
      .int()
      .min(-2147483648)
      .max(2147483647)
      .exactOptional()
      .openapi({
        description:
          "The start for gidNumbers, this number is added to a number generated from the group.pk to make sure that the numbers aren't too low for POSIX groups. Default is 4000 to ensure that we don't collide with local groups or users primary groups gidNumber",
      }),
    search_mode: LDAPAPIAccessModeSchema.exactOptional(),
    bind_mode: LDAPAPIAccessModeSchema.exactOptional(),
    mfa_support: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'When enabled, code-based multi-factor authentication can be used by appending a semicolon and the TOTP code to the password. This should only be enabled if all users that will bind to this provider have a TOTP device configured, as otherwise a password may incorrectly be rejected if it contains a semicolon.',
      }),
  })
  .openapi({
    description: 'LDAPProvider Serializer',
    required: ['application_slug', 'bind_flow_slug', 'name', 'pk', 'unbind_flow_slug'],
  })
  .openapi('LDAPOutpostConfig')

