export const getEndpointsAgentsPssoIseIndexRoute = createRoute({
  method: 'get',
  path: '/endpoints/agents/psso/ise/',
  tags: ['endpoints'],
  description: 'Mixin to add a used_by endpoint to return a list of all objects using this object',
  operationId: 'endpoints_agents_psso_ise_list',
  request: {
    query: z.object({
      apple_enclave_key_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'apple_enclave_key_id',
            schema: { type: 'string' },
            required: false,
          },
        }),
      ordering: QueryPaginationOrderingParamsSchema,
      page: QueryPaginationPageParamsSchema,
      page_size: QueryPaginationPageSizeParamsSchema,
      search: QuerySearchParamsSchema,
      user: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'user', schema: { type: 'integer' }, required: false },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: PaginatedAppleIndependentSecureEnclaveListSchema } },
    },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

