export const getEndpointsDeviceBindingsIndexRoute = createRoute({
  method: 'get',
  path: '/endpoints/device_bindings/',
  tags: ['endpoints'],
  description: 'PolicyBinding Viewset',
  operationId: 'endpoints_device_bindings_list',
  request: {
    query: z.object({
      enabled: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'enabled', schema: { type: 'boolean' }, required: false },
        }),
      order: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'order', schema: { type: 'integer' }, required: false },
        }),
      ordering: QueryPaginationOrderingParamsSchema,
      page: QueryPaginationPageParamsSchema,
      page_size: QueryPaginationPageSizeParamsSchema,
      policy: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'policy',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      policy__isnull: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'policy__isnull',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      search: QuerySearchParamsSchema,
      target: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'target',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      target_in: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.uuid()),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'target_in',
            schema: { type: 'array', items: { type: 'string', format: 'uuid' } },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
      timeout: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'timeout', schema: { type: 'integer' }, required: false },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: PaginatedDeviceUserBindingListSchema } },
    },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

