export const getEnterpriseLicenseUserCountsIndexRoute = createRoute({
  method: 'get',
  path: '/enterprise/license/user_counts/',
  tags: ['enterprise'],
  description:
    'Get active user totals and counts for relative or absolute date ranges.\n\nAt least one positive relative count step or a complete absolute range is required.\nRelative and absolute ranges may be combined. Range starts are inclusive and ends are\nexclusive. Counts include currently active, non-anonymous accounts.',
  operationId: 'enterprise_license_user_counts_retrieve',
  request: {
    query: z.object({
      count_steps: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string().min(1)).max(20),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'count_steps',
            schema: { type: 'array', items: { type: 'string', minLength: 1 }, maxItems: 20 },
            description: "Positive relative periods, such as 'days=30' or 'weeks=3;days=2'.",
            required: false,
          },
        }),
      end: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'end',
            schema: { type: 'string', format: 'date-time' },
            description: 'Exclusive end of an absolute range; must be provided with start.',
            required: false,
          },
        }),
      start: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'start',
            schema: { type: 'string', format: 'date-time' },
            description: 'Inclusive start of an absolute range; must be provided with end.',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: { description: '', content: { 'application/json': { schema: LicenseUserCountsSchema } } },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

