export const getFlowsBindingsIndexRoute = createRoute({
  method: 'get',
  path: '/flows/bindings/',
  tags: ['flows'],
  description: 'FlowStageBinding Viewset',
  operationId: 'flows_bindings_list',
  request: {
    query: z.object({
      evaluate_on_plan: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'evaluate_on_plan',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      fsb_uuid: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'fsb_uuid',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      invalid_response_action: InvalidResponseActionEnumSchema.openapi({
        param: {
          in: 'query',
          name: 'invalid_response_action',
          schema: {
            allOf: [{ $ref: '#/components/schemas/InvalidResponseActionEnum' }],
            description:
              'Configure how the flow executor should handle an invalid response to a challenge. RETRY returns the error message and a similar challenge to the executor. RESTART restarts the flow from the beginning, and RESTART_WITH_CONTEXT restarts the flow while keeping the current context.\n\n',
          },
          required: false,
        },
      }).exactOptional(),
      order: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'order', schema: { type: 'integer' }, required: false },
        }),
      ordering: QueryPaginationOrderingParamsSchema,
      page: QueryPaginationPageParamsSchema,
      page_size: QueryPaginationPageSizeParamsSchema,
      pbm_uuid: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'pbm_uuid',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      policies: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.uuid()),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'policies',
            schema: { type: 'array', items: { type: 'string', format: 'uuid' } },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
      policy_engine_mode: PolicyEngineModeSchema.openapi({
        param: {
          in: 'query',
          name: 'policy_engine_mode',
          schema: { $ref: '#/components/schemas/PolicyEngineMode' },
          required: false,
        },
      }).exactOptional(),
      re_evaluate_policies: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 're_evaluate_policies',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      search: QuerySearchParamsSchema,
      stage: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'stage',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      target: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'target',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: PaginatedFlowStageBindingListSchema } },
    },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

