export const getOauth2AccessTokensIndexRoute = createRoute({
  method: 'get',
  path: '/oauth2/access_tokens/',
  tags: ['oauth2'],
  description: 'AccessToken Viewset',
  operationId: 'oauth2_access_tokens_list',
  request: {
    query: z.object({
      ordering: QueryPaginationOrderingParamsSchema,
      page: QueryPaginationPageParamsSchema,
      page_size: QueryPaginationPageSizeParamsSchema,
      provider: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'provider', schema: { type: 'integer' }, required: false },
        }),
      search: QuerySearchParamsSchema,
      user: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'user', schema: { type: 'integer' }, required: false },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: PaginatedTokenModelListSchema } },
    },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

