export const getOutpostsInstancesIndexRoute = createRoute({
  method: 'get',
  path: '/outposts/instances/',
  tags: ['outposts'],
  description: 'Outpost Viewset',
  operationId: 'outposts_instances_list',
  request: {
    query: z.object({
      managed__icontains: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'managed__icontains',
            schema: { type: 'string' },
            required: false,
          },
        }),
      managed__iexact: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'managed__iexact',
            schema: { type: 'string' },
            required: false,
          },
        }),
      name__icontains: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'name__icontains',
            schema: { type: 'string' },
            required: false,
          },
        }),
      name__iexact: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'name__iexact', schema: { type: 'string' }, required: false },
        }),
      ordering: QueryPaginationOrderingParamsSchema,
      page: QueryPaginationPageParamsSchema,
      page_size: QueryPaginationPageSizeParamsSchema,
      providers__isnull: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'providers__isnull',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      providers_by_pk: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            ),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'providers_by_pk',
            schema: { type: 'array', items: { type: 'integer' } },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
      search: QuerySearchParamsSchema,
      service_connection__name__icontains: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'service_connection__name__icontains',
            schema: { type: 'string' },
            required: false,
          },
        }),
      service_connection__name__iexact: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'service_connection__name__iexact',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: PaginatedOutpostListSchema } },
    },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

