export const getPoliciesEventMatcherIndexRoute = createRoute({
  method: 'get',
  path: '/policies/event_matcher/',
  tags: ['policies'],
  description: 'Event Matcher Policy Viewset',
  operationId: 'policies_event_matcher_list',
  request: {
    query: z.object({
      action: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        EventActionsSchema.nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'action',
            schema: {
              allOf: [{ $ref: '#/components/schemas/EventActions' }],
              nullable: true,
              description:
                'Match created events with this action type. When left empty, all action types will be matched.\n\n',
            },
            required: false,
          },
          description:
            'Match created events with this action type. When left empty, all action types will be matched.\n\n',
        }),
      app: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'app', schema: { type: 'string' }, required: false },
        }),
      client_ip: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'client_ip', schema: { type: 'string' }, required: false },
        }),
      created: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'created',
            schema: { type: 'string', format: 'date-time' },
            required: false,
          },
        }),
      execution_logging: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'execution_logging',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      last_updated: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'last_updated',
            schema: { type: 'string', format: 'date-time' },
            required: false,
          },
        }),
      model: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'model', schema: { type: 'string' }, required: false },
        }),
      name: QueryNameParamsSchema,
      ordering: QueryPaginationOrderingParamsSchema,
      page: QueryPaginationPageParamsSchema,
      page_size: QueryPaginationPageSizeParamsSchema,
      policy_uuid: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'policy_uuid',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'query', schema: { type: 'string' }, required: false },
        }),
      search: QuerySearchParamsSchema,
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: PaginatedEventMatcherPolicyListSchema } },
    },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

