export const getSourcesScimUsersIndexRoute = createRoute({
  method: 'get',
  path: '/sources/scim_users/',
  tags: ['sources'],
  description: 'SCIMSourceUser Viewset',
  operationId: 'sources_scim_users_list',
  request: {
    query: z.object({
      ordering: QueryPaginationOrderingParamsSchema,
      page: QueryPaginationPageParamsSchema,
      page_size: QueryPaginationPageSizeParamsSchema,
      search: QuerySearchParamsSchema,
      source__slug: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'source__slug', schema: { type: 'string' }, required: false },
        }),
      user__id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'user__id', schema: { type: 'integer' }, required: false },
        }),
      user__username: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'user__username',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: PaginatedSCIMSourceUserListSchema } },
    },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

