export const getStagesAuthenticatorStaticIndexRoute = createRoute({
  method: 'get',
  path: '/stages/authenticator/static/',
  tags: ['stages'],
  description: 'AuthenticatorStaticStage Viewset',
  operationId: 'stages_authenticator_static_list',
  request: {
    query: z.object({
      configure_flow: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'configure_flow',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      friendly_name: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'friendly_name',
            schema: { type: 'string' },
            required: false,
          },
        }),
      name: QueryNameParamsSchema,
      ordering: QueryPaginationOrderingParamsSchema,
      page: QueryPaginationPageParamsSchema,
      page_size: QueryPaginationPageSizeParamsSchema,
      search: QuerySearchParamsSchema,
      stage_uuid: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'stage_uuid',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      token_count: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'token_count', schema: { type: 'integer' }, required: false },
        }),
      token_length: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'token_length',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: PaginatedAuthenticatorStaticStageListSchema } },
    },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

