export const getStagesAuthenticatorWebauthnIndexRoute = createRoute({
  method: 'get',
  path: '/stages/authenticator/webauthn/',
  tags: ['stages'],
  description: 'AuthenticatorWebAuthnStage Viewset',
  operationId: 'stages_authenticator_webauthn_list',
  request: {
    query: z.object({
      authenticator_attachment: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        AuthenticatorAttachmentEnumSchema.nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'authenticator_attachment',
            schema: {
              allOf: [{ $ref: '#/components/schemas/AuthenticatorAttachmentEnum' }],
              nullable: true,
            },
            required: false,
          },
        }),
      configure_flow: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'configure_flow',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      device_type_restrictions: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.uuid()),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'device_type_restrictions',
            schema: { type: 'array', items: { type: 'string', format: 'uuid' } },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
      max_attempts: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'max_attempts',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      name: QueryNameParamsSchema,
      ordering: QueryPaginationOrderingParamsSchema,
      page: QueryPaginationPageParamsSchema,
      page_size: QueryPaginationPageSizeParamsSchema,
      resident_key_requirement: UserVerificationEnumSchema.openapi({
        param: {
          in: 'query',
          name: 'resident_key_requirement',
          schema: { $ref: '#/components/schemas/UserVerificationEnum' },
          required: false,
        },
      }).exactOptional(),
      search: QuerySearchParamsSchema,
      user_verification: UserVerificationEnumSchema.openapi({
        param: {
          in: 'query',
          name: 'user_verification',
          schema: { $ref: '#/components/schemas/UserVerificationEnum' },
          required: false,
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: PaginatedAuthenticatorWebAuthnStageListSchema } },
    },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

