export const getStagesPasswordIndexRoute = createRoute({
  method: 'get',
  path: '/stages/password/',
  tags: ['stages'],
  description: 'PasswordStage Viewset',
  operationId: 'stages_password_list',
  request: {
    query: z.object({
      allow_show_password: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'allow_show_password',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      configure_flow: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'configure_flow',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      failed_attempts_before_cancel: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'failed_attempts_before_cancel',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      name: QueryNameParamsSchema,
      ordering: QueryPaginationOrderingParamsSchema,
      page: QueryPaginationPageParamsSchema,
      page_size: QueryPaginationPageSizeParamsSchema,
      search: QuerySearchParamsSchema,
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: PaginatedPasswordStageListSchema } },
    },
    400: ValidationErrorResponseResponse,
    403: GenericErrorResponseResponse,
  },
  security: [{ authentik: [] }],
})

